async function allowedFixture_Org_revokeInvitation(h: AverriTestHarness, input: Record<string, unknown>): Promise<string> {
  for (const fixture of FIXTURES) {
    if (fixture === "anonymous") continue;
    const env: Env = { input, actor: h.actor(fixture) };
    await seedPolicy_Org_revokeInvitation(h, env, "satisfy", fixture);
    const decision = await h.policyDecision("Action:Org.revokeInvitation", fixture, input);
    if (decision === "allow" || decision === "public" || decision === "opaque") return fixture;
  }
  throw new Error("no actor fixture in FIXTURES is allowed by Policy:Org.OwnerOrAdmin for this input; add a fixture to config.actors or seed the rows the policy needs");
}

async function invokeAllowed_Org_revokeInvitation(h: AverriTestHarness, input: Record<string, unknown>, options?: { headers?: Record<string, string> }): Promise<{ res: Invoked; fixture: string; env: Env }> {
  const fixture = await allowedFixture_Org_revokeInvitation(h, input);
  const env: Env = { input, actor: h.actor(fixture) };
  await seedRequires_Org_revokeInvitation(h, env);
  await seedSubject_Org_revokeInvitation(h, env);
  const res = await h.invoke("Action:Org.revokeInvitation", fixture, input, options);
  return { res, fixture, env };
}

void input_valid_Org_revokeInvitation; void invokeAllowed_Org_revokeInvitation;

// --- suites ---

describe("[Test:gen/Invitation.invariant]", () => {
  // Every invariant is evaluated over findMany() of the model (observe-mode diff; declared mode also reports it as 500 PostconditionFailed).
  const INVARIANTS = ["Contract:Invitation.invariant.pendingHasNoAcceptedAt", "Contract:Invitation.invariant.acceptedHasAcceptor", "Contract:Invitation.invariant.revokedHasTimestamp", "Contract:Invitation.invariant.roleIsGrantable", "Contract:Invitation.invariant.resendCountNonNegative"];
  it("[Test:gen/Invitation.invariant] invariants hold on the current rows", async () => {
    expect(await h.invariantViolations("Entity:Invitation")).toEqual([]);
  });
  // writers skipped: Action:Org.acceptInvite
  const WRITERS = ["Action:Org.inviteMember", "Action:Org.revokeInvitation"] as const;
  async function runWriter(writer: (typeof WRITERS)[number]): Promise<Invoked> {
    switch (writer) {
      case "Action:Org.inviteMember": {
        const input = drawInput(h, "Action:Org.inviteMember", input_valid_Org_inviteMember);
        return (await invokeAllowed_Org_inviteMember(h, input)).res;
      }
      case "Action:Org.revokeInvitation": {
        const input = drawInput(h, "Action:Org.revokeInvitation", input_valid_Org_revokeInvitation);
        return (await invokeAllowed_Org_revokeInvitation(h, input)).res;
      }
    }
  }
  it("[Test:gen/Invitation.invariant] 1-5 generated writes preserve the invariants", async () => {
    await fc.assert(fc.asyncProperty(fc.array(fc.constantFrom(...WRITERS), { minLength: 1, maxLength: 5 }), async (sequence) => {
      for (const writer of sequence) {
        const res = await runWriter(writer);
        if (res.status === 500) expect(INVARIANTS, `${writer} reported an invariant failure`).not.toContain(errorBody(res).contract);
        expect(await h.invariantViolations("Entity:Invitation"), `after ${writer}`).toEqual([]);
      }
    }), { numRuns: NUM_RUNS });
  }, PROPERTY_TIMEOUT_MS);
});
